import static org.junit.Assert.assertNotNull;

public class BasePeriod_toDurationTo_TriageGen1Test {

    @Test
    public void testToDurationTo_StandardPeriod() {
        // Create a period of 1 hour
        Period period = new Period(1, 0, 0, 0, 1, 0, 0, 0, PeriodType.standard());

        // End instant: 2023-01-01T12:00:00Z
        DateTime endInstant = new DateTime(2023, 1, 1, 12, 0, 0, 0);

        // Expected: The period is 1 hour, so startMillis should be endMillis - 1 hour
        // Duration(start, end)
        Duration result = period.toDurationTo(endInstant);

        assertNotNull(result);
        assertEquals(3600000L, result.getStandardMillis());
        assertEquals(endInstant.getMillis(), result.getEndMillis());
    }

    @Test
    public void testToDurationTo_DaysPeriod() {
        // Create a period of 2 days
        Period period = new Period(0, 0, 0, 2, 0, 0, 0, 0, PeriodType.standard());

        // End instant
        DateTime endInstant = new DateTime(2023, 5, 10, 10, 0, 0, 0);

        // The method uses chrono.add(this, endMillis, -1)
        // This logic effectively calculates the interval that ends at endInstant and has the given period
        Duration result = period.toDurationTo(endInstant);

        assertNotNull(result);
        // 2 days in millis = 2 * 24 * 60 * 60 * 1000 = 172800000
        assertEquals(172800000L, result.getStandardMillis());
    }

    @Test
    public void testToDurationTo_WithDifferentChronology() {
        // Test with a different chronology if applicable, though standard is default
        Period period = new Period(0, 0, 0, 0, 0, 30, 0, 0, PeriodType.standard());
        DateTime endInstant = new DateTime(2023, 1, 1, 0, 0, 30, 0);

        Duration result = period.toDurationTo(endInstant);

        assertNotNull(result);
        assertEquals(30000L, result.getStandardMillis());
    }

    @Test
    public void testToDurationTo_ZeroPeriod() {
        Period period = new Period(0, 0, 0, 0, 0, 0, 0, 0, PeriodType.standard());
        DateTime endInstant = new DateTime(2023, 1, 1, 0, 0, 0, 0);

        Duration result = period.toDurationTo(endInstant);

        assertNotNull(result);
        assertEquals(0L, result.getStandardMillis());
    }

    @Test
    public void testToDurationTo_LargeMillis() {
        // Test with a period representing a large number of millis
        long millis = 86400000L; // 1 day
        Period period = new Period(0, 0, 0, 1, 0, 0, 0, 0, PeriodType.standard());
        DateTime endInstant = new DateTime(2023, 1, 1, 0, 0, 0, 0);

        Duration result = period.toDurationTo(endInstant);

        assertNotNull(result);
        assertEquals(millis, result.getStandardMillis());
    }

    @Test
    public void testToDurationTo_EdgeCaseInstant() {
        // Test with the epoch
        Period period = new Period(0, 0, 0, 0, 0, 0, 0, 1000, PeriodType.standard());
        Instant endInstant = new Instant(0);

        Duration result = period.toDurationTo(endInstant);

        assertNotNull(result);
        assertEquals(1000L, result.getStandardMillis());
        assertEquals(0L, result.getEndMillis());
    }
}
